    gaps = [c["name"] for c in controls if (not _failed(c["flags"])) and _gap(c["flags"])]
    if gaps:
        return (
            "UNRESOLVED-DESIGN",
            "eligible control fails no evaluable core criterion while an essential comparison is unavailable: "
            + ", ".join(gaps),
