    idx = solver.idx
    py = solver.world.py[z]
    A, B = {}, {}
    pk = pol[k]
    for i, p in recipients:
        ctrl = i if donor is None else donor
        for y in range(N_Y):
            a = pk[ctrl * N_Y + y]
            w = p * py[y]
            if a != R_ACT:
                A[ctrl] = A.get(ctrl, F(0)) + w
                B[i] = B.get(i, F(0)) + w
