                    return False
        return True

    def correct_R(self, b: Fraction, y: int) -> Fraction:
        if self.invariant:
            return b * self.kappa[0][y] + (1 - b) * self.kappa[1][y]
        return self.world.expected_correct_R(b, b, y)

